public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n || k == 0) return false;
    int totalCodes = 1 << k;
    if (totalCodes > n - k + 1) return false; // impossible to cover all codes
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int cur = 0;
    // Build the first code
    for (int i = 0; i < k; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    seen[cur] = true;
    int seenCount = 1;
    // Slide over the string
    for (int i = k; i < n; i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[cur]) {
            seen[cur] = true;
            seenCount++;
        }
    }
    return seenCount == totalCodes;
}

