public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // need to insert a '(' before this ')'
            } else {
                balance--;       // match this ')' with an existing '('
            }
        }
    }
    // remaining unmatched '(' need a ')' each
    return insertions + balance;
}

