public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        if (s % 2 == 0) {
            int iStart = Math.min(s, m - 1);
            int iEnd = Math.max(0, s - (n - 1));
            for (int i = iStart; i >= iEnd; i--) {
                int j = s - i;
                result[idx++] = mat[i][j];
            }
        } else {
            int iStart = Math.max(0, s - (n - 1));
            int iEnd = Math.min(s, m - 1);
            for (int i = iStart; i <= iEnd; i++) {
                int j = s - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    // Check for duplicate points
    if ((x0 == x1 && y0 == y1) || (x0 == x2 && y0 == y2) || (x1 == x2 && y1 == y2)) {
        return false;
    }

    // Compute twice the area of the triangle formed by the points
    long area2 = (long)(x1 - x0) * (y2 - y0) - (long)(x2 - x0) * (y1 - y0);
    return area2 != 0;
}

