        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

/**
 * Calculates the energy of the string, defined as the length of the longest non‑empty
 * substring that contains only one repeated character.
 *
 * @param s the input string
 * @return the energy of the string
 */
public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
            prev = c;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

